import * as THREE from './three.module.js';
import {createCourtShoe} from './shoes.js';
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),up=new THREE.Vector3(0,1,0);
export function bodyMotion(phase,hand,plant,speed,height=1){const low=clamp((1-height)*.12,0,.10)*plant;return {shoulders:phase*hand*.62,hips:phase*hand*.29,lower:.065*plant+low,bob:(1-plant)*Math.min(speed/6,1)*.014,weightX:-hand*.045*Math.abs(phase),weightZ:.055*plant+Math.max(0,phase)*.04,lean:.055*plant+low*.7};}
export function createFootwork(skin,white){const root=new THREE.Group(),legs=[];function bone(r,m){const mesh=new THREE.Mesh(new THREE.CapsuleGeometry(r,1-2*r,6,24),m);mesh.castShadow=true;root.add(mesh);return mesh;}function fit(m,a,b){const d=b.clone().sub(a);m.position.copy(a).add(b).multiplyScalar(.5);m.scale.y=d.length();m.quaternion.setFromUnitVectors(up,d.normalize());}
 for(const side of [-1,1]){const thigh=bone(.087,skin),shin=bone(.057,skin),shorts=bone(.108,white),sock=bone(.062,white),knee=new THREE.Mesh(new THREE.SphereGeometry(.059,24,16),skin),shoe=createCourtShoe(white,side);root.add(knee,shoe);legs.push({side,thigh,shin,shorts,sock,knee,shoe,foot:new THREE.Vector3(side*.17,.10,0),anchor:null});}
 let cycle=0,lastPlant=0;
 function pose(dt,{speed=0,vx=0,vz=0,plant=0,hand=1,hipYaw=0,bodyX=0,bodyZ=0,baseYaw=0,crouch=.065*plant}={}){const shuffle=Math.abs(vx)>Math.abs(vz)*.8&&speed<3.4,stride=(shuffle?.4:.85)*clamp(speed/3,.28,1)*(1-.65*plant);cycle+=speed*dt*.60/stride;const dx=speed>.05?vx/speed:0,dz=speed>.05?vz/speed:1;const cx=Math.cos(baseYaw),sx=Math.sin(baseYaw),lx=cx*dx-sx*dz,lz=sx*dx+cx*dz;
 for(let i=0;i<2;i++){const l=legs[i],phase=(cycle+i*.5)%1;let progress,lift;if(phase<.4){const u=phase/.4;progress=-.5+u*u*(3-2*u);lift=Math.sin(u*Math.PI)*(shuffle?.065:.12);}else{progress=.5-(phase-.4)/.6;lift=0;}
 const moving=speed>.12?1:0;let desired=new THREE.Vector3(l.side*(.17+.065*plant)+lx*stride*progress*moving,.10+lift*moving,lz*stride*progress*moving);
 if(plant>.45){if(lastPlant<=.45||!l.anchor){l.anchor=new THREE.Vector3(bodyX+cx*(l.foot.x+l.side*.065)+sx*l.foot.z,0,bodyZ-sx*(l.foot.x+l.side*.065)+cx*l.foot.z);}const wx=l.anchor.x-bodyX,wz=l.anchor.z-bodyZ;const fixed=new THREE.Vector3(cx*wx-sx*wz,.10,sx*wx+cx*wz);fixed.x=clamp(fixed.x,l.side*.17-.35,l.side*.17+.35);fixed.z=clamp(fixed.z,-.38,.38);desired.lerp(fixed,plant);}else l.anchor=null;
 const blend=1-Math.exp(-dt*22);l.foot.lerp(desired,blend);const hip=new THREE.Vector3(l.side*.15*Math.cos(hipYaw),.81-crouch,-l.side*.15*Math.sin(hipYaw)),ankle=l.foot.clone(),d=ankle.clone().sub(hip),distance=clamp(d.length(),.12,.735);d.normalize();ankle.copy(hip).addScaledVector(d,distance);const L1=.37,L2=.38,a=(L1*L1-L2*L2+distance*distance)/(2*distance),height=Math.sqrt(Math.max(0,L1*L1-a*a)),pole=new THREE.Vector3(0,0,1);pole.addScaledVector(d,-pole.dot(d)).normalize();const knee=hip.clone().addScaledVector(d,a).addScaledVector(pole,height);fit(l.thigh,hip,knee);fit(l.shin,knee,ankle);fit(l.shorts,hip,hip.clone().lerp(knee,.63));fit(l.sock,knee.clone().lerp(ankle,.69),ankle);l.knee.position.copy(knee);l.shoe.position.copy(ankle).add(new THREE.Vector3(0,-.035,.05));l.shoe.rotation.x=plant>.45?0:(phase<.4?-Math.sin(phase/.4*Math.PI)*.12:Math.max(0,(phase-.75)/.25)*.10)*moving;l.shoe.rotation.y=(plant>.45?clamp(hipYaw*.15,-.08,.08):clamp(lx,-1,1)*moving*.08)+l.side*.025;
 }lastPlant=plant;}
 pose(0);return {root,pose,legs};}
